const byId = (id: string) => listings.find((l) => l.id === id)!;



const items = (...ids: string[]) => ids.map((id) => toTradeItem(byId(id)));

/** Build a shipment that has walked through every stage up to `stage`. */
function shipped(stage: ShipStage, start: string, extra: Partial<Shipment> = {}): Shipment {
  const end = SHIP_STAGES.indexOf(stage);
  const t0 = new Date(start).getTime();
  const history = SHIP_STAGES.slice(0, end + 1).map((s, i) => ({
    stage: s,
    at: new Date(t0 + i * 14 * 3600_000).toISOString(),
  }));
  const pastLabel = end >= SHIP_STAGES.indexOf("label_created");
  return {
    stage,
    history,
    packingChecklist: pastLabel ? [...PACKING_CHECKLIST] : [],
    trackingCode: pastLabel ? extra.trackingCode : undefined,
    ...extra,
  };
}

const fresh = (at: string): Shipment => ({
  stage: "awaiting_agreement",
  history: [{ stage: "awaiting_agreement", at }],
  packingChecklist: [],
});

function signed(trade: Omit<Trade, "agreement">, signedAt: string): Trade {
  const agreement = buildAgreement(trade as Trade, trade.createdAt);
  agreement.signatures = { proposer: signedAt, receiver: signedAt };
  return { ...trade, agreement };
}

